package ai.nethra.planner;
import ai.nethra.common.*; import ai.nethra.planner.client.*; import ai.nethra.planner.graph.TravelGraph; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.test.context.bean.override.mockito.MockitoBean;
import java.math.BigDecimal; import java.time.*; import java.util.*;
import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
@SpringBootTest class TravelGraphIntegrationTest {
  @MockitoBean BudgetClient budgetClient; @MockitoBean DestinationClient destinationClient; @MockitoBean TransportClient transportClient; @MockitoBean HotelClient hotelClient; @MockitoBean ActivityClient activityClient; @MockitoBean PartnerClient partnerClient; @MockitoBean ItineraryClient itineraryClient; @MockitoBean NotificationClient notificationClient;
  @Autowired TravelGraph graph;
  @BeforeEach void stubs(){
    when(budgetClient.allocate(any())).thenAnswer(inv -> { BudgetAllocationRequest r=inv.getArgument(0); BigDecimal buffer=Moneys.percent(r.budgetInr(),8); EnumMap<BudgetCategory,BigDecimal> m=new EnumMap<>(BudgetCategory.class); m.put(BudgetCategory.TRANSPORT,Moneys.percent(r.budgetInr(),30)); m.put(BudgetCategory.HOTEL,Moneys.percent(r.budgetInr(),30)); m.put(BudgetCategory.FOOD,Moneys.percent(r.budgetInr(),17)); m.put(BudgetCategory.ACTIVITIES,Moneys.percent(r.budgetInr(),15)); m.put(BudgetCategory.EMERGENCY_BUFFER,buffer); return new BudgetAllocationResponse(r.budgetInr(), r.budgetInr().subtract(buffer), buffer, m, List.of("test allocation")); });
    when(destinationClient.minimums(anyString(), anyInt(), anyInt(), nullable(TransportMode.class))).thenAnswer(inv -> TripCostEstimator.allMinimums(inv.getArgument(0), inv.getArgument(1), inv.getArgument(2), inv.getArgument(3)));
    when(destinationClient.rank(anyString(), any(), any(), anyInt(), anyInt())).thenAnswer(inv -> { TransportMode mode=inv.getArgument(1); BigDecimal budget=inv.getArgument(2); DestinationProfile p = (mode==TransportMode.FLIGHT && budget.compareTo(new BigDecimal("25000"))>=0) ? TravelCatalog.find("goa").orElseThrow() : TravelCatalog.find("bengaluru").orElseThrow(); return List.of(new DestinationRank(p,new BigDecimal("92.00"),new BigDecimal("10000"),new BigDecimal("1000"),"test rank")); });
    when(transportClient.options(anyString(), anyString(), any(), any(), anyInt())).thenAnswer(inv -> { String dest=inv.getArgument(1); TransportMode mode=inv.getArgument(2); LocalDate date=inv.getArgument(3); BigDecimal price="goa".equals(dest)?new BigDecimal("6000"):new BigDecimal("950"); return List.of(new TransportOption("test-option",mode,"Test Mock Provider","Source",dest,date==null?LocalDate.now():date,"morning",price,new BigDecimal("5.0"),true,new BigDecimal("90"))); });
    when(partnerClient.packages(anyString(), anyInt(), anyInt())).thenAnswer(inv -> { String dest=inv.getArgument(0); if(!"goa".equals(dest)) return List.of(); DestinationProfile goa=TravelCatalog.find("goa").orElseThrow(); return PartnerCatalog.forDestination("goa").stream().map(p->PartnerCatalog.quote(p,goa,inv.getArgument(1),inv.getArgument(2))).toList(); });
    when(hotelClient.hotels(anyString(), nullable(BigDecimal.class))).thenAnswer(inv -> List.of(new Hotel("h1",inv.getArgument(0),"Test Comfort Stay","Centre",3,new BigDecimal("1500"),new BigDecimal("4.3"),new BigDecimal("88"),true,true)));
    when(activityClient.activities(anyString())).thenAnswer(inv -> ActivityCatalog.forDestination(inv.getArgument(0)));
    when(itineraryClient.plan(any())).thenAnswer(inv -> { ItineraryRequest r=inv.getArgument(0); List<DayPlan> days=new ArrayList<>(); for(int i=0;i<r.days();i++){ List<DayPlan.ItinerarySlot> slots=new ArrayList<>(); if(r.activities()!=null && !r.activities().isEmpty()){ ActivityItem a=r.activities().get(i % r.activities().size()); slots.add(new DayPlan.ItinerarySlot("09:00",a.name(),a.description(),a.price())); } days.add(new DayPlan(i+1,"Day "+(i+1)+" in "+r.destinationName(),slots,BigDecimal.ZERO)); } return new ItineraryPlan(r.destinationName(),days,BigDecimal.ZERO); });
    when(notificationClient.send(any())).thenReturn(new NotificationResponse("n1","demo@nethra.ai","EMAIL","ok","LOGGED_BY_MOCK_SENDER",Instant.now()));
  }
  @Test void specExampleHyderabadFlightIsRejected(){ TravelPlanResponse r=graph.run(new PlanRequest(new BigDecimal("15000"),"Hyderabad",4,TransportMode.FLIGHT,1)); System.out.println("Spec example minimumRequiredBudget=" + r.minimumRequiredBudget()); assertFalse(r.feasible()); assertNull(r.itinerary()); assertTrue(r.minimumRequiredBudget().compareTo(new BigDecimal("15000"))>0, "minimum was " + r.minimumRequiredBudget()); assertTrue(r.alternativeTransportModes().stream().anyMatch(m->m.transportMode()==TransportMode.TRAIN)); assertFalse(r.alternativeDestinations().isEmpty()); assertFalse(r.suggestions().isEmpty()); }
  @Test void feasibleTrainTripStaysWithinBudget(){ TravelPlanResponse r=graph.run(new PlanRequest(new BigDecimal("15000"),"Hyderabad",3,TransportMode.TRAIN,1)); assertTrue(r.feasible(), () -> String.valueOf(r.agentTrace())); assertEquals("Bengaluru", r.destination().name()); assertEquals(3, r.itinerary().days().size()); assertTrue(r.totalCost().compareTo(new BigDecimal("15000"))<=0, "total was " + r.totalCost()); assertEquals(0, new BigDecimal("1200.00").compareTo(r.costBreakdown().get(BudgetCategory.EMERGENCY_BUFFER))); assertEquals(r.request().budgetInr().subtract(r.totalCost()), r.remainingBudget()); }
  @Test void partnerPackageIsPreferredWhenItFits(){ TravelPlanResponse r=graph.run(new PlanRequest(new BigDecimal("30000"),"Mumbai",4,TransportMode.FLIGHT,1)); assertTrue(r.feasible(), () -> String.valueOf(r.agentTrace())); assertNotNull(r.partnerPackage()); assertEquals("Goa Partner Package", r.partnerPackage().partnerPackage().name()); assertNull(r.hotel()); assertTrue(r.agentTrace().stream().anyMatch(s->s.decision().equals("PARTNER_PACKAGE_SELECTED"))); verify(hotelClient, never()).hotels(anyString(), any()); }
}
